sys_variable_value.value:
(function(outputs, steps, params, stepResult, assertEqual) {
    var origEnabled = gs.getProperty('x_2241073_securi_0.api.enabled', 'false');
    var origUrl = gs.getProperty('x_2241073_securi_0.api.url', '');

    gs.setProperty('x_2241073_securi_0.api.enabled', 'true');
    gs.setProperty('x_2241073_securi_0.api.url', 'https://test.example.com/webhook');

    var caseId = '';
    try {
        var caseGR = new GlideRecord('x_2241073_securi_0_sec_case');
        caseGR.initialize();
        caseGR.setValue('short_description', 'ATF Outbound Severity Test');
        caseGR.setValue('severity', '3');
        caseGR.setValue('case_source', 'torq');
        caseGR.setValue('torq_incident_id', 'ATF-OUTBOUND-SEV-001');
        caseId = caseGR.insert();

        var updateGR = new GlideRecord('x_2241073_securi_0_sec_case');
        if (updateGR.get(caseId)) {
            updateGR.setValue('severity', '1');
            updateGR.update();
        }

        var logGR = new GlideRecord('x_2241073_securi_0_webhook_log');
        logGR.addQuery('case_id', caseId);
        logGR.addQuery('direction', 'outbound');
        logGR.addQuery('status', 'pending');
        logGR.query();
        var count = logGR.getRowCount();

        assertEqual({
            name: 'Outbound webhook log created for severity change',
            shouldbe: 'true',
            value: String(count > 0)
        });

        if (logGR.next()) {
            var payload = logGR.getValue('payload');
            var hasEventType = payload.indexOf('case.severity_changed') > -1;
            assertEqual({
                name: 'Payload contains severity_changed event type',
                shouldbe: 'true',
                value: String(hasEventType)
            });
        }

        stepResult.setOutputMessage('Found ' + count + ' pending outbound webhook(s) for severity change');
    } finally {
        // Cleanup webhook logs and test case
        if (caseId) {
            var cleanLog = new GlideRecord('x_2241073_securi_0_webhook_log');
            cleanLog.addQuery('case_id', caseId);
            cleanLog.query();
            while (cleanLog.next()) { cleanLog.deleteRecord(); }

            var cleanCase = new GlideRecord('x_2241073_securi_0_sec_case');
            if (cleanCase.get(caseId)) { cleanCase.deleteRecord(); }
        }
        gs.setProperty('x_2241073_securi_0.api.enabled', origEnabled);
        gs.setProperty('x_2241073_securi_0.api.url', origUrl);
    }
})(outputs, steps, params, stepResult, assertEqual);

